<script lang="ts">
 import { onMount } from 'svelte'; import { request } from './api'; import { PageHeader, RefreshButton } from './ui';
 type Customer={id:string;name:string;email:string;phone:string};type Document={id:string;kind:string;number:string;status:string;issue_date:string;due_date?:string;total_cents:number;counterparty:string};
 let customers=$state<Customer[]>([]),documents=$state<Document[]>([]),name=$state(''),email=$state(''),kind=$state('invoice'),description=$state('Jasa'),quantity=$state(1),price=$state(0),error=$state(''),saving=$state(false);
 const money=(value:number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value/100);
 async function load(){try{const x=await request<{customers:Customer[];documents:Document[]}>('/v1/admin/commercial');customers=x.customers;documents=x.documents;}catch(e){error=e instanceof Error?e.message:'Komersial tidak dapat dimuat.';}}
 async function customer(){saving=true;try{await request('/v1/admin/commercial/customers',{method:'POST',body:JSON.stringify({name,email})});name='';email='';await load();}finally{saving=false;}}
 async function document(){saving=true;try{await request('/v1/admin/commercial',{method:'POST',body:JSON.stringify({kind,issue_date:new Date().toISOString().slice(0,10),lines:[{description,quantity:Number(quantity),unit_price_cents:Number(price)}]})});await load();}finally{saving=false;}}
 onMount(load);
</script>
<main class="workspace-page"><PageHeader title="Commercial" description="Customer, quotation, invoice, vendor bill, dan pembayaran dalam satu buku kerja." backHref="/admin/dashboard"/>{#if error}<p class="alert">{error}</p>{/if}<div class="grid"><section class="panel"><h2>Customer</h2><form novalidate onsubmit={(e)=>{e.preventDefault();void customer();}}><input bind:value={name} placeholder="Nama customer" required/><input bind:value={email} type="email" placeholder="Email"/><button disabled={saving}>Tambah customer</button></form><ul>{#each customers as item (item.id)}<li><strong>{item.name}</strong><small>{item.email||item.phone||'—'}</small></li>{:else}<li class="muted">Belum ada customer.</li>{/each}</ul></section><section class="panel"><h2>Dokumen baru</h2><form novalidate onsubmit={(e)=>{e.preventDefault();void document();}}><select bind:value={kind}><option value="quote">Quotation</option><option value="invoice">Invoice</option><option value="vendor_bill">Vendor bill</option></select><input bind:value={description} placeholder="Deskripsi" required/><div class="twocol"><input bind:value={quantity} type="number" min="1"/><input bind:value={price} type="number" min="0" placeholder="Harga (sen)"/></div><button disabled={saving}>Terbitkan dokumen</button></form></section></div><section class="panel"><header><h2>Dokumen terbaru</h2><RefreshButton onclick={load} label="Muat ulang"/></header>{#each documents as item (item.id)}<article><div><strong>{item.number}</strong><small>{item.kind} · {item.counterparty||'Tanpa customer'} · {item.issue_date}</small></div><div><strong>{money(item.total_cents)}</strong><small>{item.status}</small></div></article>{:else}<p class="muted">Belum ada dokumen.</p>{/each}</section></main>
<style>.workspace-page,.grid{display:grid;gap:12px}.grid{grid-template-columns:1fr 1fr}.panel{padding:16px;border-radius:var(--radius)}form{display:grid;gap:8px}.twocol,article{display:grid;grid-template-columns:1fr 1fr;gap:8px}article{border-top:1px solid var(--line);padding:10px 0;align-items:center}article>div:last-child{text-align:right}small{display:block;color:var(--muted);font-size:12px}.alert{color:var(--danger)}ul{padding:0;list-style:none}li{padding:8px 0;border-top:1px solid var(--line)}@media(max-width:720px){.grid{grid-template-columns:1fr}}</style>
